import json
from pathlib import Path

import pytest

from repoutils.commands.check_pins import main
from repoutils.locked_actions import LockError, check, read_actions_lock, read_uv_lock

COMMIT = "0123456789abcdef0123456789abcdef01234567"
OTHER = "fedcba9876543210fedcba9876543210fedcba98"

ACTIONS_LOCK = f"""\
# This file is machine-generated by `gh actions-lock`.
version: 'v0.0.3'
workflows:
    '.github/workflows/ci.yml':
        - 'actions/checkout@v7.0.1'
        - 'Example/Tool/.github/actions/setup@v1.2.0'
    '.github/workflows/other.yml':
        - 'example/tool@v1.2.0'
dependencies:
    'actions/checkout@v7.0.1':
        ref: 'v7.0.1'
        commit: 'sha1-3d3c42e5aac5ba805825da76410c181273ba90b1'
        owner_id: 44036562
        repo_id: 197814629
    'Example/Tool/.github/actions/setup@v1.2.0':
        ref: 'v1.2.0'
        commit: 'sha1-{COMMIT}'
        owner_id: 1
        repo_id: 2
        uses:
            - 'example/tool@{OTHER}'
    'example/tool@v1.2.0':
        ref: 'v1.2.0'
        commit: 'sha1-{COMMIT}'
        owner_id: 1
        repo_id: 2
    'example/tool@{OTHER}':
        ref: 'v1.1.0'
        commit: 'sha1-{OTHER}'
        owner_id: 1
        repo_id: 2
"""

UV_LOCK = """\
version = 1

[[package]]
name = "example-tool"
version = "1.2.0"
source = { registry = "https://pypi.org/simple" }

[[package]]
name = "unrelated"
version = "3.0"
source = { registry = "https://pypi.org/simple" }

[[package]]
name = "not-installed"
version = "1.0"
source = { registry = "https://pypi.org/simple" }

[[package]]
name = "project"
source = { virtual = "." }
"""


def install(
    site: Path,
    name: str,
    version: str,
    repository: str | None = "https://github.com/example/tool",
    info: object = None,
    info_path: str = "example_tool/build_info.json",
) -> None:
    """A distribution in site, with build_info.json at info_path (listed in
    its RECORD) unless info is None."""
    dist_info = site / f"{name.replace('-', '_')}-{version}.dist-info"
    dist_info.mkdir(parents=True)
    metadata = f"Metadata-Version: 2.4\nName: {name}\nVersion: {version}\nProject-URL: Homepage, https://example.com\n"
    if repository is not None:
        metadata += f"Project-URL: Source-Code, https://example.com/x\nProject-URL: repository, {repository}\n"
    (dist_info / "METADATA").write_text(metadata)
    record = [f"{dist_info.name}/METADATA,,", f"{dist_info.name}/RECORD,,"]
    if info is not None:
        (site / info_path).parent.mkdir(parents=True, exist_ok=True)
        (site / info_path).write_text(info if isinstance(info, str) else json.dumps(info))
        record.append(f"{info_path},,")
    (dist_info / "RECORD").write_text("\n".join(record) + "\n")


@pytest.fixture
def project(tmp_path: Path) -> Path:
    root = tmp_path / "project"
    (root / ".github/workflows").mkdir(parents=True)
    (root / ".github/workflows/actions.lock").write_text(ACTIONS_LOCK)
    (root / "uv.lock").write_text(UV_LOCK)
    install(tmp_path / "site", "unrelated", "3.0", "https://github.com/someone/else", {"commit": OTHER, "dirty": True})
    return root


def site(project: Path) -> list[str]:
    return [str(project.parent / "site")]


def test_read_actions_lock_accepts_empty_sections() -> None:
    assert read_actions_lock("version: 'v0.0.3'\nworkflows: {}\ndependencies: {}\n") == []


def test_read_actions_lock_accepts_a_workflow_with_no_actions() -> None:
    """Also an action that uses no actions, which isn't checked."""
    text = ACTIONS_LOCK.replace("workflows:\n", "workflows:\n    '.github/workflows/empty.yml': []\n").replace(
        f"        uses:\n            - 'example/tool@{OTHER}'\n", "        uses: []\n"
    )
    assert text.count("[]") == 2
    assert [a.key for a in read_actions_lock(text)] == [a.key for a in read_actions_lock(ACTIONS_LOCK)]


def test_read_actions_lock_takes_only_direct_actions() -> None:
    actions = read_actions_lock(ACTIONS_LOCK)
    assert [(a.key, a.repo, a.ref, a.commit) for a in actions] == [
        ("Example/Tool/.github/actions/setup@v1.2.0", "example/tool", "v1.2.0", COMMIT),
        ("actions/checkout@v7.0.1", "actions/checkout", "v7.0.1", "3d3c42e5aac5ba805825da76410c181273ba90b1"),
        ("example/tool@v1.2.0", "example/tool", "v1.2.0", COMMIT),
    ]


@pytest.mark.parametrize(
    ("text", "error"),
    [
        ("workflows:\n  '.github/workflows/a.yml':\n", r"actions\.lock:2: unexpected line"),
        ("version: 'v1'\nworkflows: [\ndependencies:\n", r"actions\.lock:2: unexpected line 'workflows: \['"),
        (
            "workflows:\n    'a.yml': []\n        - 'a/b@v1'\ndependencies: {}\n",
            r"actions\.lock:3: unexpected line \"- 'a/b@v1'\"",
        ),
        ("workflows: {}\ndependencies:\n    'a/b@v1': []\n", r"actions\.lock:3: unexpected line \"'a/b@v1': \[\]\""),
        ("workflows:\n", "no dependencies section"),
        ("", "no workflows or dependencies section"),
        ("workflows:\n    'a.yml':\n        - 'nope'\ndependencies:\n", "'nope' isn't of the form"),
        ("workflows:\n    'a.yml':\n        - 'a/b@v1'\ndependencies: {}\n", "a/b@v1 has no entry under dependencies"),
        (
            "workflows:\n    'a.yml':\n        - 'a/b@v1'\ndependencies:\n    'a/b@v1':\n        ref: 'v1'\n",
            "a/b@v1 has no ref or no commit",
        ),
    ],
)
def test_read_actions_lock_rejects_what_it_cant_read(text: str, error: str) -> None:
    with pytest.raises(LockError, match=error):
        read_actions_lock(text)


def test_read_uv_lock() -> None:
    assert read_uv_lock(UV_LOCK) == {"example-tool": ["1.2.0"], "unrelated": ["3.0"], "not-installed": ["1.0"]}
    for text, error in [
        ("version = ", "uv.lock: "),
        ("package = 3\n", "package isn't a list"),
        ("[[package]]\nversion = '1'\n", "a package has no name"),
        ("[[package]]\nname = 'a'\nversion = 1\n", "a's version isn't a string"),
    ]:
        with pytest.raises(LockError, match=error):
            read_uv_lock(text)


def test_matching_commit_passes(project: Path, capsys: pytest.CaptureFixture[str]) -> None:
    install(project.parent / "site", "example-tool", "1.2.0", info={"commit": COMMIT, "dirty": False})
    result = check(project, site(project))
    assert (result.problems, result.warnings) == ([], [])
    assert result.matched == [f"example-tool 1.2.0's actions are at its commit {COMMIT[:12]}"]


def test_build_info_is_found_wherever_record_puts_it(project: Path) -> None:
    # A Repository URL with .git and a trailing slash still names the repository.
    install(
        project.parent / "site",
        "example-tool",
        "1.2.0",
        "https://GitHub.com/Example/Tool.git",
        {"commit": COMMIT.upper(), "dirty": False},
        "somewhere/else/build_info.json",
    )
    assert check(project, site(project)).problems == []


def test_different_commit_or_dirty_build_fails(project: Path) -> None:
    install(project.parent / "site", "example-tool", "1.2.0", info={"commit": OTHER, "dirty": True})
    assert check(project, site(project)).problems == [
        f"example-tool 1.2.0 was built with uncommitted changes to {OTHER[:12]}",
        f"actions.lock: Example/Tool/.github/actions/setup@v1.2.0 is at commit {COMMIT[:12]}, "
        f"but uv.lock's example-tool 1.2.0 was built from {OTHER[:12]}",
        f"actions.lock: example/tool@v1.2.0 is at commit {COMMIT[:12]}, "
        f"but uv.lock's example-tool 1.2.0 was built from {OTHER[:12]}",
    ]


@pytest.mark.parametrize("info", [None, {"commit": None, "dirty": None}])
def test_without_build_info_the_tag_is_checked_with_a_warning(project: Path, info: object) -> None:
    install(project.parent / "site", "example-tool", "1.2.0", info=info)
    result = check(project, site(project))
    assert result.problems == []
    assert result.matched == ["example-tool 1.2.0's actions are at v1.2.0"]
    assert result.warnings == [
        "warning: example-tool 1.2.0 has no build_info.json, so only "
        "Example/Tool/.github/actions/setup@v1.2.0's ref was checked against v1.2.0, not its commit",
        "warning: example-tool 1.2.0 has no build_info.json, so only "
        "example/tool@v1.2.0's ref was checked against v1.2.0, not its commit",
    ]


def test_without_build_info_another_tag_fails(project: Path) -> None:
    (project / "uv.lock").write_text(UV_LOCK.replace('"1.2.0"', '"1.3.0"'))
    install(project.parent / "site", "example-tool", "1.3.0")
    result = check(project, site(project))
    assert result.matched == []
    assert result.problems == [
        "actions.lock: Example/Tool/.github/actions/setup@v1.2.0 is at v1.2.0, "
        "but uv.lock pins example-tool 1.3.0, so it should be v1.3.0",
        "actions.lock: example/tool@v1.2.0 is at v1.2.0, but uv.lock pins example-tool 1.3.0, so it should be v1.3.0",
    ]


def test_installed_version_must_match_uv_lock(project: Path) -> None:
    install(project.parent / "site", "example-tool", "1.1.0", info={"commit": COMMIT, "dirty": False})
    with pytest.raises(LockError, match=r"example-tool 1\.1\.0 is installed, but uv\.lock pins 1\.2\.0, so"):
        check(project, site(project))
    # uv.lock can have more than one version of a package, for different markers.
    second = '[[package]]\nname = "example-tool"\nversion = "{}"\nsource = {{ registry = "https://pypi.org/simple" }}\n'
    (project / "uv.lock").write_text(UV_LOCK + "\n" + second.format("1.3.0"))
    with pytest.raises(LockError, match=r"uv\.lock pins 1\.2\.0 or 1\.3\.0, so"):
        check(project, site(project))
    (project / "uv.lock").write_text(UV_LOCK + "\n" + second.format("1.1.0"))
    assert check(project, site(project)).matched == [f"example-tool 1.1.0's actions are at its commit {COMMIT[:12]}"]


@pytest.mark.parametrize(
    ("info", "error"),
    [
        ("{", "build_info.json can't be read"),
        ([], "isn't of the form"),
        ({"commit": 3, "dirty": False}, "isn't of the form"),
        ({"commit": COMMIT, "dirty": "no"}, "isn't of the form"),
        ({"commit": COMMIT, "dirty": None}, "isn't of the form"),
        ({"commit": None, "dirty": True}, "isn't of the form"),
        ({}, "isn't of the form"),
    ],
)
def test_unreadable_build_info_is_an_error(project: Path, info: object, error: str) -> None:
    install(project.parent / "site", "example-tool", "1.2.0", info=info)
    with pytest.raises(LockError, match=error):
        check(project, site(project))


def test_a_build_info_that_record_lists_must_exist(project: Path) -> None:
    site_dir = project.parent / "site"
    install(site_dir, "example-tool", "1.2.0", info={"commit": COMMIT, "dirty": False})
    (site_dir / "example_tool/build_info.json").unlink()
    with pytest.raises(LockError, match="build_info.json can't be read"):
        check(project, site(project))


def test_a_package_without_record_is_an_error(project: Path) -> None:
    site_dir = project.parent / "site"
    install(site_dir, "example-tool", "1.2.0")
    (site_dir / "example_tool-1.2.0.dist-info/RECORD").unlink()
    with pytest.raises(LockError, match="example-tool has no readable RECORD"):
        check(project, site(project))


def test_two_build_infos_are_an_error(project: Path) -> None:
    site_dir = project.parent / "site"
    install(site_dir, "example-tool", "1.2.0", info={"commit": COMMIT, "dirty": False})
    (site_dir / "other").mkdir()
    (site_dir / "other/build_info.json").write_text("{}")
    with (site_dir / "example_tool-1.2.0.dist-info/RECORD").open("a") as record:
        record.write("other/build_info.json,,\n")
    with pytest.raises(LockError, match="more than one build_info.json"):
        check(project, site(project))


@pytest.mark.parametrize("repository", [None, "https://gitlab.com/example/tool", "https://github.com/example/other"])
def test_packages_from_other_repositories_are_skipped(project: Path, repository: str | None) -> None:
    install(project.parent / "site", "example-tool", "1.1.0", repository)
    assert check(project, site(project)).matched == []


def test_nothing_to_check_without_both_lock_files(project: Path) -> None:
    install(project.parent / "site", "example-tool", "1.1.0")
    (project / "uv.lock").unlink()
    assert check(project, site(project)).problems == []
    (project / "uv.lock").write_text(UV_LOCK)
    (project / ".github/workflows/actions.lock").unlink()
    assert check(project, site(project)).problems == []


def test_unreadable_lock_file_is_an_error(project: Path) -> None:
    (project / "uv.lock").write_bytes(b"\xff")
    with pytest.raises(LockError, match="can't decode"):
        check(project, site(project))


def test_without_a_path_it_looks_in_sys_path(project: Path, monkeypatch: pytest.MonkeyPatch) -> None:
    install(project.parent / "site", "example-tool", "1.2.0", info={"commit": COMMIT, "dirty": False})
    monkeypatch.syspath_prepend(str(project.parent / "site"))
    assert check(project).matched == [f"example-tool 1.2.0's actions are at its commit {COMMIT[:12]}"]


def write_pinned_project(root: Path) -> None:
    """The files check-pins' other checks need, all passing."""
    (root / "pyproject.toml").write_text('[tool.uv]\nrequired-version = ">=0.13.6"\n')
    (root / "justfile").write_text("set minimum-version := '1.58.0'\n")
    (root / ".github/workflows/a.yml").write_text(
        "jobs:\n  a:\n    steps:\n      - uses: astral-sh/setup-uv@v7\n        with:\n          version: 0.13.6\n"
        "      - uses: extractions/setup-just@v3\n        with:\n          just-version: 1.58.0\n"
    )


def test_check_pins_reports_the_check(project: Path, capsys: pytest.CaptureFixture[str]) -> None:
    write_pinned_project(project)
    install(project.parent / "site", "example-tool", "1.2.0")
    assert main(project, site(project)) == 0
    out, err = capsys.readouterr()
    assert out.splitlines()[1:] == ["example-tool 1.2.0's actions are at v1.2.0"]
    assert err.count("warning: ") == 2


def test_check_pins_fails_on_an_error_with_the_other_problems(
    project: Path, capsys: pytest.CaptureFixture[str]
) -> None:
    write_pinned_project(project)
    (project / ".github/workflows/a.yml").write_text("jobs:\n  a:\n    steps:\n      - run: echo\n")
    (project / ".github/workflows/actions.lock").write_text("workflows:\n  bad\n")
    assert main(project, site(project)) == 1
    assert capsys.readouterr().err.splitlines() == [
        "no workflow or action has a astral-sh/setup-uv step",
        "no workflow or action has a extractions/setup-just step",
        ".github/workflows/actions.lock:2: unexpected line 'bad'",
    ]
